import{K as l,a as r,c as i,b as t,k as c,q as d,ac as h}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"Excel 图表、趋势与数据表达","description":"根据比较、趋势和构成选择图表，从部门汇总制作柱形图，设置数据源、坐标轴、单位、标签和误导性图形检查。","frontmatter":{"title":"Excel 图表、趋势与数据表达","description":"根据比较、趋势和构成选择图表，从部门汇总制作柱形图，设置数据源、坐标轴、单位、标签和误导性图形检查。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"使用指南","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · Excel 表格与数据分析","summary":"根据比较、趋势和构成选择图表，从部门汇总制作柱形图，设置数据源、坐标轴、单位、标签和误导性图形检查。","status":"active","related":[{"title":"Excel 实战：建立可刷新、可核对的月报","link":"/tools/office/excel/project","kind":"实践案例","scope":"general","audience":"general"},{"title":"Office 常见问题排查与交付检查表","link":"/tools/office/collaboration/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Office 常用快捷键、选择与粘贴技巧","link":"/tools/office/start/shortcuts","kind":"参考资料","scope":"general","audience":"general"},{"title":"Office 综合实战：从数据到报告、演示和会议","link":"/tools/office/collaboration/workflow","kind":"实践案例","scope":"general","audience":"general"},{"title":"Word 实战：制作可维护的项目报告","link":"/tools/office/word/report","kind":"实践案例","scope":"general","audience":"general"}],"prev":{"text":"Excel 数据验证、条件格式与重复检查","link":"/tools/office/excel/validation"},"next":{"text":"Excel 数据透视表、切片器与透视图","link":"/tools/office/excel/pivots"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Excel 数据验证、条件格式与重复检查","link":"/tools/office/excel/validation"},"next":{"text":"Excel 数据透视表、切片器与透视图","link":"/tools/office/excel/pivots"}},"headers":[],"relativePath":"tools/office/excel/charts.md","filePath":"tools/office/excel/charts.md"}'),n={name:"tools/office/excel/charts.md"},k=Object.assign(n,{setup(s){const a={path:"/tools/office/excel/charts",app:"Excel",title:"从汇总表生成能解释的柱形图",steps:[{tab:"插入",command:"柱形图",setting:"数据：运营 2440、技术 720；口径：十月已完成",anchor:"walkthrough-1"},{tab:"图表设计",command:"添加图表元素",setting:"标题：十月已完成金额（元）；显示数据标签",anchor:"walkthrough-2"},{tab:"图表设计",command:"选择数据",setting:"核对系列区域；金额变化后图形同步",anchor:"walkthrough-3"}]};return(f,e)=>{const o=l("OfficeGuide");return r(),i("div",null,[e[0]||(e[0]=t("h1",{id:"excel-图表、趋势与数据表达",tabindex:"-1"},[c("Excel 图表、趋势与数据表达 "),t("a",{class:"header-anchor",href:"#excel-图表、趋势与数据表达","aria-label":'Permalink to "Excel 图表、趋势与数据表达"'},"​")],-1)),e[1]||(e[1]=t("p",null,"先写清楚图表要回答的问题，再选择样式。把全部原始数据直接框选成图，常常只是得到许多颜色，并没有让人更容易理解。",-1)),d(o,{guide:a}),e[2]||(e[2]=h('<h2 id="choose" tabindex="-1">根据问题选图 <a class="header-anchor" href="#choose" aria-label="Permalink to &quot;根据问题选图 {#choose}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>常用图表</th><th>需要避免</th></tr></thead><tbody><tr><td>哪个部门金额更多</td><td>条形图、柱形图</td><td>用大量饼图扇区比较接近数值</td></tr><tr><td>月度指标如何变化</td><td>折线图</td><td>把无顺序的类别连成趋势线</td></tr><tr><td>两个数值是否有关系</td><td>散点图</td><td>把相关关系说成因果关系</td></tr><tr><td>一组数据如何分布</td><td>直方图</td><td>把连续数值当成无关类别</td></tr><tr><td>总量由哪些部分组成</td><td>堆积柱形图，少量类别的饼图</td><td>正负值混在不合适的构成图中</td></tr></tbody></table><p>金额和完成率单位不同，若用组合图与次坐标轴，要明确标注两套单位，并解释为什么放在一起。轴的尺度会影响视觉比较，不能只为了两条线“看起来相关”而调整。</p><h2 id="create" tabindex="-1">制作部门金额柱形图 <a class="header-anchor" href="#create" aria-label="Permalink to &quot;制作部门金额柱形图 {#create}&quot;">​</a></h2><p>根据<a href="/tools/office/excel/start#data">练习数据</a>，在 <code>汇总</code> 表 A1:B4 输入部门和全部订单金额：运营 2440、技术 1620、财务 1060。真实使用时应通过公式或透视表生成汇总，这里先用已知结果练习图表操作。</p><ol><li>选择 A1:B4，点击“插入 → 柱形图 → 簇状柱形图”。</li><li>把图表标题改为“全部订单金额按部门分布”，不要使用容易误解的“已完成收入”。</li><li>增加纵轴标题“金额（元）”，统一数值格式。</li><li>单系列图一般不需要重复的图例，可直接显示数据标签。</li><li>将部门按金额降序排列，确认排序后的类别和数值仍然一一对应。</li></ol><p>财务的 1060 包含待处理 900 和已取消 160；如果业务问题是“已完成金额”，财务应为 0。这说明图表可以在技术上画对，却使用了错误口径。</p><h2 id="source" tabindex="-1">检查数据源与轴 <a class="header-anchor" href="#source" aria-label="Permalink to &quot;检查数据源与轴 {#source}&quot;">​</a></h2><p>右击图表“选择数据”，核对系列名称、系列值和横轴标签范围。新增一行后图表是否扩展，取决于源数据是否为表格、图表引用和具体操作，必须实际检查，不凭外观推断。</p><p>柱形和条形图通常应从零开始，因为长度承担数值比较。折线图若缩小纵轴范围，应保留清楚刻度并说明变化幅度。日期显示顺序错误时检查日期是否为文本；数据点不连续时先确认缺失值，不能随意用零替代未知值。</p><h2 id="readability" tabindex="-1">标签、颜色与阅读 <a class="header-anchor" href="#readability" aria-label="Permalink to &quot;标签、颜色与阅读 {#readability}&quot;">​</a></h2><p>优先使用清晰的二维图，减少渐变、阴影和三维效果。标题写发现或比较对象，副说明写时间、单位、样本范围和筛选条件。颜色数量以读者需要分辨的系列为准；关键系列可突出，其余保持中性。</p><p>数值标签只显示足以理解的精度，例如金额到元或万元、比例到一位小数。图很小但标签很多时，应扩大图表或减少类别，不只缩小字体。颜色之外还可用线型、标签或标记区分系列。</p><h2 id="practice" tabindex="-1">练习与验收 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;练习与验收 {#practice}&quot;">​</a></h2><p>分别制作“全部订单金额”和“已完成金额”两张部门图。后一张应为运营 2440、技术 1620、财务 0。检查标题是否准确解释差异；把图表复制到 PowerPoint 后，以实际放映尺寸查看文字是否可读。</p><p>如果图表用于交付，在旁边写明数据文件、统计截止时间和是否可刷新。下一篇<a href="/tools/office/excel/pivots">透视表</a>会让汇总和图表更容易更新。</p><h2 id="walkthrough" tabindex="-1">图示跟做：从汇总表生成能解释的柱形图 <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：从汇总表生成能解释的柱形图 {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：先画小汇总表再插图 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：先画小汇总表再插图 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：插入 → 柱形图。</strong></p><p>在空白工作表建“部门、金额”两列，录入运营 2440、技术 720，这是八条订单中十月已完成的汇总。选中表头和两行数据，选择“插入 → 柱形图 → 簇状柱形图”。不要把全部明细直接画成看似有结论的部门图。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：补齐读者需要的上下文 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：补齐读者需要的上下文 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：图表设计 → 添加图表元素。</strong></p><p>选中图表，设置标题和单位，显示数据标签，观察横轴是否是部门而不是默认序号。标题外注明日期范围及状态条件；颜色少而一致，柱形图金额轴通常从零开始。隐藏多余图例时先确认颜色无需依赖图例才能理解。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：用一次数据变化检查链接 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：用一次数据变化检查链接 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：图表设计 → 选择数据。</strong></p><p>在副本中把运营金额暂改成 2520，确认柱高和标签同步变化，再恢复 2440。新增部门后检查图表数据区域是否扩展。最后缩小到报告实际显示尺寸，看部门名和单位能否读清；在编辑界面放大看清不等于投影或打印可读。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>图中有数据但分类错位时，先检查选择数据中的系列和轴标签。不要靠手动改数据标签文字伪装修复，否则源值更新后标签与图形可能分离。</p>',29))])}}});export{u as __pageData,k as default};
